import backtrader as bt


class PowerHourReversal(bt.Strategy):
    params = dict(
        rsi_period=14,
        ema_period=20,
        oversold=30,
        overbought=70,
        take_profit_pct=0.015,
        stop_loss_pct=0.008,
        position_pct=0.02,
        volatility_threshold=0.015,
        last_hour=15,
    )

    def __init__(self):
        self.rsi = bt.indicators.RSI(self.data.close, period=self.p.rsi_period)
        self.ema = bt.indicators.EMA(self.data.close, period=self.p.ema_period)

        self.order = None
        self.entry_price = None

        self.current_day = None
        self.day_high = None
        self.day_low = None

    def notify_order(self, order):
        if order.status == order.Completed:
            if self.position.size != 0:
                self.entry_price = order.executed.price
            else:
                self.entry_price = None
        if order.status in [order.Completed, order.Canceled, order.Margin, order.Rejected]:
            self.order = None

    def next(self):
        bar_date = self.data.datetime.date(0)
        bar_time = self.data.datetime.time(0)

        if self.current_day is None or bar_date != self.current_day:
            self.current_day = bar_date
            self.day_high = self.data.high[0]
            self.day_low = self.data.low[0]
        else:
            self.day_high = max(self.day_high, self.data.high[0])
            self.day_low = min(self.day_low, self.data.low[0])

        if self.order:
            return

        is_last_hour = bar_time.hour == self.p.last_hour
        price = self.data.close[0]

        if self.position:
            if self.entry_price is not None:
                if self.position.size > 0:
                    if price >= self.entry_price * (1 + self.p.take_profit_pct):
                        self.order = self.close()
                        return
                    if price <= self.entry_price * (1 - self.p.stop_loss_pct):
                        self.order = self.close()
                        return
                elif self.position.size < 0:
                    if price <= self.entry_price * (1 - self.p.take_profit_pct):
                        self.order = self.close()
                        return
                    if price >= self.entry_price * (1 + self.p.stop_loss_pct):
                        self.order = self.close()
                        return

            if is_last_hour:
                self.order = self.close()
            return

        if not is_last_hour:
            return

        daily_range_pct = (self.day_high - self.day_low) / self.day_low
        if daily_range_pct <= self.p.volatility_threshold:
            return

        long_signal = (
            price < self.ema[0]
            and self.rsi[-1] < self.p.oversold
            and self.rsi[0] > self.p.oversold
        )
        short_signal = (
            price > self.ema[0]
            and self.rsi[-1] > self.p.overbought
            and self.rsi[0] < self.p.overbought
        )

        if not (long_signal or short_signal):
            return

        size = int((self.p.position_pct * self.broker.getvalue()) / price)
        if size <= 0:
            return

        if long_signal:
            self.order = self.buy(size=size)
        elif short_signal:
            self.order = self.sell(size=size)
